public long maxHourglassSum(int[][] grid) {
    int n = grid.length;
    long best = Long.MIN_VALUE;
    for (int r = 0; r <= n - 3; r++) {
        for (int c = 0; c <= n - 3; c++) {
            long sum = 0;
            for (int dr = 0; dr < 3; dr++) {
                for (int dc = 0; dc < 3; dc++) {
                    if (dr == 1 && (dc == 0 || dc == 2)) continue;
                    sum += grid[r + dr][c + dc];
                }
            }
            best = Math.max(best, sum);
        }
    }
    return best;
}

