public long maxHourglassSum(int[][] grid) {
    int n = grid.length;
    long best = Long.MIN_VALUE;
    for (int r = 0; r + 2 < n; r++) {
        for (int c = 0; c + 2 < n; c++) {
            long sum = grid[r][c] + grid[r][c + 1] + grid[r][c + 2]
                     + grid[r + 1][c + 1]
                     + grid[r + 2][c] + grid[r + 2][c + 1] + grid[r + 2][c + 2];
            best = Math.max(best, sum);
        }
    }
    return best;
}

